    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    open_count_1 = lst[0].count('(')
    close_count_1 = lst[0].count(')')
    open_count_2 = lst[1].count('(')
    close_count_2 = lst[1].count(')')

    if open_count_1 != close_count_1 or open_count_2 != close_count_2:
        return 'No'

    combined_strings = [lst[0] + lst[1], lst[1] + lst[0]]

    for combined_string in combined_strings:
        if is_balanced(combined_string):
            return 'Yes'

    return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: 'Yes'
print(match_parens([')', ')']))     # Output: 'No'
